cask "appgrid" do
  version "1.0"
  sha256 "b08cdeeb10af0bf0f7464299cd02da7844790e272dd634b14d165f28df583012"

  url "https://github.com/SAASEmpiree/homebrew-tap/releases/download/appgrid-v#{version}/appgrid-#{version}.zip"
  name "AppGrid"
  desc "Keeps Finder's Applications windows laid out as a 6-column, iPhone-style icon grid"
  homepage "https://github.com/SAASEmpiree/homebrew-tap#appgrid"

  depends_on arch: :arm64
  depends_on macos: :tahoe

  app "AppGrid.app"

  # AppGrid is a background helper (no window, no Dock icon): run it at login through a launch agent.
  postflight do
    agent = File.expand_path("~/Library/LaunchAgents/com.saasempiree.appgrid.plist")
    FileUtils.mkdir_p File.dirname(agent)
    File.write agent, <<~PLIST
      <?xml version="1.0" encoding="UTF-8"?>
      <!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
      <plist version="1.0">
      <dict>
        <key>Label</key><string>com.saasempiree.appgrid</string>
        <key>ProgramArguments</key>
        <array><string>#{appdir}/AppGrid.app/Contents/MacOS/AppGrid</string></array>
        <key>RunAtLoad</key><true/>
        <key>KeepAlive</key><true/>
        <key>ProcessType</key><string>Interactive</string>
      </dict>
      </plist>
    PLIST
    system_command "/bin/launchctl", args: ["bootout", "gui/#{Process.uid}/com.saasempiree.appgrid"], must_succeed: false
    system_command "/bin/launchctl", args: ["bootstrap", "gui/#{Process.uid}", agent]
  end

  uninstall launchctl: "com.saasempiree.appgrid",
            quit:      "com.saasempiree.appgrid"

  zap trash: [
    "~/Library/Application Support/com.saasempiree.appgrid",
    "~/Library/Caches/com.saasempiree.appgrid",
    "~/Library/HTTPStorages/com.saasempiree.appgrid",
    "~/Library/Preferences/com.saasempiree.appgrid.plist",
    "~/Library/Saved Application State/com.saasempiree.appgrid.savedState",
    "~/Library/WebKit/com.saasempiree.appgrid",
  ]

  caveats <<~EOS
    AppGrid runs in the background (launch agent com.saasempiree.appgrid): it has no window.
    On first use, allow it to control Finder (Automation) when macOS asks.

    AppGrid is signed with the SAASEmpiree self-signed certificate, not notarized by Apple.
    If macOS refuses to open it the first time, run once:
      xattr -dr com.apple.quarantine "#{appdir}/AppGrid.app"
  EOS
end
